import * as React from 'react'
import { ArrowDown, LoaderCircle, MessageSquare } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { ChatMessage, type ChatMessageProps } from '@/components/ui/chat-message'
import { useAsyncAction, clamp } from '@/components/ui/product-utils'
import { cn } from '@/lib/utils'
import type { TextStreamOptions } from '@/components/ui/text-stream'
export interface ConversationProps extends React.ComponentProps<'section'>, TextStreamOptions {
  messages: ChatMessageProps[]
  label?: string
  height?: number
  loading?: boolean
  hasEarlier?: boolean
  onLoadEarlier?: (options: { signal: AbortSignal }) => void | Promise<void>
  renderMessage?: (message: ChatMessageProps) => React.ReactNode
  emptyState?: React.ReactNode
  footer?: React.ReactNode
  autoScroll?: boolean
}
interface ConversationContext extends ConversationProps {
  scrollRef: React.RefObject<HTMLDivElement | null>
  stuck: boolean
  setStuck: (value: boolean) => void
  unread: number
  setUnread: (value: number) => void
  busy: boolean
  load: () => void
  jump: () => void
}
const Context = React.createContext<ConversationContext | null>(null)
const useConversation = () => {
  const c = React.useContext(Context)
  if (!c) throw new Error('Conversation parts need Conversation.')
  return c
}
/** Bottom-following transcript that preserves a reader's position and anchors prepended history. */
export function Conversation({
  messages,
  label = 'Conversation',
  height = 520,
  loading = false,
  hasEarlier = false,
  onLoadEarlier,
  renderMessage,
  emptyState,
  footer,
  autoScroll = true,
  textAnimation = 'typewriter',
  charactersPerSecond = 60,
  children,
  className,
  ...props
}: ConversationProps) {
  const scrollRef = React.useRef<HTMLDivElement>(null),
    [stuck, setStuck] = React.useState(true),
    [unread, setUnread] = React.useState(0),
    [announcement, setAnnouncement] = React.useState<{ id: string; text: string } | null>(null),
    previousMessages = React.useRef(messages),
    pendingAnnouncements = React.useRef(new Set<string>()),
    action = useAsyncAction(),
    stickRef = React.useRef(true),
    before = React.useRef<{ first?: string; last?: string; height: number; length: number }>({
      height: 0,
      length: 0,
    })
  React.useLayoutEffect(() => {
    stickRef.current = stuck
  }, [stuck])
  const jump = () => {
    const el = scrollRef.current
    if (el) {
      el.scrollTop = el.scrollHeight
      setStuck(true)
      setUnread(0)
    }
  }
  React.useLayoutEffect(() => {
    const el = scrollRef.current
    if (!el) return
    const prev = before.current,
      first = messages[0]?.id,
      last = messages.at(-1)?.id,
      prepend =
        prev.first !== undefined &&
        first !== prev.first &&
        messages.some((message) => message.id === prev.first)
    if (prepend) el.scrollTop += el.scrollHeight - prev.height
    else if (autoScroll && stickRef.current) el.scrollTop = el.scrollHeight
    else if (last !== prev.last && messages.length > prev.length)
      setUnread((count) => count + messages.length - prev.length)
    const near = el.scrollHeight - el.scrollTop - el.clientHeight < 72
    stickRef.current = near
    setStuck(near)
    if (near) setUnread(0)
    before.current = { first, last, height: el.scrollHeight, length: messages.length }
  }, [messages, autoScroll])
  React.useEffect(() => {
    const previous = previousMessages.current,
      oldIds = new Set(previous.map((message) => message.id)),
      last = previous.at(-1)?.id,
      start = last ? messages.findIndex((message) => message.id === last) + 1 : 0,
      currentIds = new Set(messages.map((message) => message.id))
    if (!last || start > 0)
      for (const message of messages.slice(start))
        if (!oldIds.has(message.id)) pendingAnnouncements.current.add(message.id)
    for (const id of pendingAnnouncements.current)
      if (!currentIds.has(id)) pendingAnnouncements.current.delete(id)
    const completed = messages.filter(
      (message) => pendingAnnouncements.current.has(message.id) && message.status !== 'streaming',
    )
    if (completed.length) {
      setAnnouncement({
        id: completed.at(-1)!.id,
        text: completed
          .map(
            (message) =>
              `${message.author ?? message.role}: ${message.copyText ?? (typeof message.content === 'string' ? message.content : 'New message.')}`,
          )
          .join('\n'),
      })
      for (const message of completed) pendingAnnouncements.current.delete(message.id)
    }
    previousMessages.current = messages
  }, [messages])
  React.useEffect(() => {
    const el = scrollRef.current,
      content = el?.querySelector('[data-conversation-content]')
    if (!el || !content || typeof ResizeObserver === 'undefined') return
    const observer = new ResizeObserver(() => {
      if (autoScroll && stickRef.current) el.scrollTop = el.scrollHeight
      const near = el.scrollHeight - el.scrollTop - el.clientHeight < 72
      stickRef.current = near
      setStuck(near)
      if (near) setUnread(0)
      before.current.height = el.scrollHeight
    })
    observer.observe(content)
    return () => observer.disconnect()
  }, [autoScroll])
  const load = () => {
    if (!action.busy && !loading && onLoadEarlier)
      void action.run((signal) => onLoadEarlier({ signal }))
  }
  const valid =
    new Set(messages.map((message) => message.id)).size === messages.length &&
    messages.every((message) => !!message.id)
  return (
    <Context.Provider
      value={{
        messages,
        label,
        height,
        loading,
        hasEarlier,
        onLoadEarlier,
        renderMessage,
        emptyState,
        footer,
        autoScroll,
        textAnimation,
        charactersPerSecond,
        scrollRef,
        stuck,
        setStuck: (value) => {
          stickRef.current = value
          setStuck(value)
        },
        unread,
        setUnread,
        busy: action.busy,
        load,
        jump,
      }}
    >
      <section
        {...props}
        data-slot="conversation"
        aria-label={label}
        className={cn(
          'relative w-full min-w-0 overflow-hidden rounded-xl border bg-background',
          className,
        )}
      >
        <div
          role="log"
          aria-live="polite"
          aria-atomic="true"
          aria-relevant="additions text"
          aria-label="Conversation updates"
          className="sr-only"
        >
          {announcement && <p key={announcement.id}>{announcement.text}</p>}
        </div>
        {!valid ? (
          <p role="alert" className="p-4 text-sm text-destructive">
            Messages need unique, stable IDs.
          </p>
        ) : (
          (children ?? (
            <>
              <ConversationMessages />
              <ConversationJumpToLatest />
              {footer && <ConversationFooter>{footer}</ConversationFooter>}
            </>
          ))
        )}
        {action.error && (
          <p role="alert" className="border-t p-3 text-xs text-destructive">
            {action.error}
          </p>
        )}
      </section>
    </Context.Provider>
  )
}
export function ConversationMessages() {
  const c = useConversation()
  return (
    <div
      ref={c.scrollRef}
      tabIndex={0}
      aria-label="Message transcript"
      className="relative overflow-y-auto overscroll-contain p-3 outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring sm:p-4"
      style={{ height: clamp(c.height ?? 520, 180, 1600), overflowAnchor: 'none' }}
      onScroll={(event) => {
        const el = event.currentTarget,
          near = el.scrollHeight - el.scrollTop - el.clientHeight < 72
        c.setStuck(near)
        if (near) c.setUnread(0)
      }}
    >
      <div data-conversation-content className="space-y-3">
        {c.hasEarlier && (
          <div className="text-center">
            <Button
              type="button"
              size="sm"
              variant="ghost"
              disabled={c.busy || c.loading || !c.onLoadEarlier}
              onClick={c.load}
            >
              {(c.busy || c.loading) && <LoaderCircle className="animate-spin" />}Load earlier
              messages
            </Button>
          </div>
        )}
        {!c.messages.length &&
          !c.loading &&
          (c.emptyState ?? (
            <div
              role="status"
              className="grid min-h-48 place-content-center gap-3 text-center text-sm text-muted-foreground"
            >
              <MessageSquare className="mx-auto size-7" />
              Start a conversation.
            </div>
          ))}
        {c.messages.map((message) => (
          <React.Fragment key={message.id}>
            {c.renderMessage?.(message) ?? (
              <ChatMessage
                textAnimation={c.textAnimation}
                charactersPerSecond={c.charactersPerSecond}
                {...message}
              />
            )}
          </React.Fragment>
        ))}
        {c.loading && (
          <p
            role="status"
            className="flex items-center justify-center gap-2 p-3 text-xs text-muted-foreground"
          >
            <LoaderCircle className="size-4 animate-spin" />
            Loading messages…
          </p>
        )}
      </div>
    </div>
  )
}
export function ConversationJumpToLatest() {
  const c = useConversation()
  return !c.stuck && c.messages.length > 0 ? (
    <div className="pointer-events-none sticky bottom-3 z-10 -mt-10 flex justify-center pb-3">
      <Button
        type="button"
        size="sm"
        variant="secondary"
        onClick={c.jump}
        className="pointer-events-auto rounded-full border shadow-sm"
      >
        <ArrowDown />
        {c.unread ? `${c.unread} new ${c.unread === 1 ? 'message' : 'messages'}` : 'Jump to latest'}
      </Button>
    </div>
  ) : null
}
export function ConversationFooter({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div {...props} data-slot="conversation-footer" className={cn('border-t p-3', className)} />
  )
}

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { Slot } from 'radix-ui'
import { Loader2 } from 'lucide-react'

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground hover:bg-primary/90',
        destructive:
          'bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40',
        outline:
          'border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50',
        secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
        link: 'text-primary underline-offset-4 hover:underline',
        soft: 'bg-primary/10 text-primary hover:bg-primary/15',
        success: 'bg-emerald-600 text-white hover:bg-emerald-700',
        warning: 'bg-amber-400 text-amber-950 hover:bg-amber-500',
        dashed:
          'border border-dashed bg-background text-foreground hover:border-primary hover:text-primary',
      },
      size: {
        default:
          'h-[var(--ergon-control-height,2.25rem)] px-4 py-[var(--ergon-control-py,0.5rem)] has-[>svg]:px-3',
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: 'h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5',
        lg: 'h-10 rounded-md px-6 has-[>svg]:px-4',
        icon: 'size-9',
        'icon-xs': "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        'icon-sm': 'size-8',
        'icon-lg': 'size-10',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

/**
 * Composes button variants, loading state, and optional slot rendering. Compact-density styles travel with the installed source.
 */
function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }) {
  const Comp = asChild ? Slot.Root : 'button'

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size }), className)}
      aria-busy={loading || undefined}
      {...props}
      disabled={props.disabled || loading}
    >
      {asChild ? (
        children
      ) : (
        <>
          {loading && <Loader2 className="animate-spin" />}
          {children}
        </>
      )}
    </Comp>
  )
}

export { Button, buttonVariants }

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import * as React from 'react'
import {
  Copy,
  Check,
  Pencil,
  RotateCcw,
  ThumbsUp,
  ThumbsDown,
  Bot,
  User,
  ChevronLeft,
  ChevronRight,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { useAsyncAction } from '@/components/ui/product-utils'
import { cn } from '@/lib/utils'
import { useTextStream, type TextStreamOptions } from '@/components/ui/text-stream'
export interface ChatMessageProps
  extends Omit<React.ComponentProps<'article'>, 'content' | 'id' | 'onCopy'>, TextStreamOptions {
  id: string
  role: 'user' | 'assistant' | 'system' | 'tool'
  content: React.ReactNode
  author?: string
  avatar?: React.ReactNode
  status?: 'complete' | 'streaming' | 'error' | 'cancelled'
  copyText?: string
  createdAt?: string
  metadata?: React.ReactNode
  onEdit?: (text: string, options: { signal: AbortSignal }) => void | Promise<void>
  onRetry?: (options: { signal: AbortSignal }) => void | Promise<void>
  onCopy?: (text: string) => void | Promise<void>
  rating?: 'up' | 'down' | null
  onRatingChange?: (rating: 'up' | 'down' | null) => void
  branches?: { id: string; label: string }[]
  branchId?: string
  onBranchChange?: (id: string) => void
}
interface MessageContext extends ChatMessageProps {
  text: string
  editing: boolean
  setEditing: (value: boolean) => void
  busy: boolean
  run: ReturnType<typeof useAsyncAction>['run']
}
const Context = React.createContext<MessageContext | null>(null)
const useMessage = () => {
  const c = React.useContext(Context)
  if (!c) throw new Error('Message parts need ChatMessage.')
  return c
}
export function ChatMessage({
  id,
  role,
  content,
  author,
  avatar,
  status = 'complete',
  textAnimation = 'typewriter',
  charactersPerSecond = 60,
  copyText,
  createdAt,
  metadata,
  onEdit,
  onRetry,
  onCopy,
  rating,
  onRatingChange,
  branches,
  branchId,
  onBranchChange,
  children,
  className,
  ...props
}: ChatMessageProps) {
  const action = useAsyncAction(),
    [editing, setEditing] = React.useState(false),
    text = copyText ?? (typeof content === 'string' ? content : ''),
    { cancel } = action
  React.useEffect(() => {
    cancel()
    setEditing(false)
  }, [id, cancel])
  return (
    <Context.Provider
      value={{
        id,
        role,
        content,
        author,
        avatar,
        status,
        textAnimation,
        charactersPerSecond,
        createdAt,
        metadata,
        onEdit,
        onRetry,
        onCopy,
        rating,
        onRatingChange,
        branches,
        branchId,
        onBranchChange,
        text,
        editing,
        setEditing,
        busy: action.busy,
        run: action.run,
      }}
    >
      <article
        {...props}
        data-slot="chat-message"
        data-role={role}
        data-status={status}
        aria-label={`${author ?? role} message`}
        className={cn(
          'group min-w-0 rounded-xl px-4 py-4',
          role === 'user' ? 'border bg-muted/40' : 'bg-background',
          className,
        )}
      >
        {children ?? (
          <>
            <ChatMessageHeader />
            <ChatMessageContent />
            <ChatMessageActions />
          </>
        )}
        {action.error && (
          <p role="alert" className="mt-2 text-xs text-destructive">
            {action.error}
          </p>
        )}
      </article>
    </Context.Provider>
  )
}
export function ChatMessageHeader() {
  const c = useMessage()
  return (
    <header className="mb-3 flex items-center gap-2">
      <span className="grid size-7 shrink-0 place-content-center rounded-lg border bg-background text-muted-foreground">
        {c.avatar ??
          (c.role === 'assistant' ? <Bot className="size-4" /> : <User className="size-4" />)}
      </span>
      <span className="text-xs font-semibold capitalize">{c.author ?? c.role}</span>
      {c.createdAt && Number.isFinite(Date.parse(c.createdAt)) && (
        <time dateTime={c.createdAt} className="text-[10px] text-muted-foreground">
          {new Date(c.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
        </time>
      )}
      {c.status !== 'complete' && (
        <span
          role="status"
          className={cn(
            'ms-auto text-[10px] capitalize text-muted-foreground',
            c.status === 'error' && 'text-destructive',
          )}
        >
          {c.status === 'streaming' ? 'Writing…' : c.status}
        </span>
      )}
    </header>
  )
}
export function ChatMessageContent() {
  const c = useMessage(),
    [draft, setDraft] = React.useState(c.text)
  const { text, isRevealing } = useTextStream(typeof c.content === 'string' ? c.content : '', {
    streaming: c.status === 'streaming',
    textAnimation: c.textAnimation,
    charactersPerSecond: c.charactersPerSecond,
    streamKey: JSON.stringify([c.id, c.branchId]),
    immediate: c.editing || c.status === 'cancelled' || c.status === 'error',
  })
  React.useEffect(() => {
    if (c.editing) setDraft(c.text)
  }, [c.editing, c.text])
  return c.editing ? (
    <div className="space-y-2">
      <Textarea
        aria-label="Edit message"
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        disabled={c.busy}
        rows={3}
      />
      <div className="flex gap-2">
        <Button
          type="button"
          size="sm"
          disabled={c.busy || !draft.trim()}
          onClick={() =>
            void c.run(async (signal) => {
              await c.onEdit?.(draft, { signal })
              if (!signal.aborted) c.setEditing(false)
            })
          }
        >
          Save edit
        </Button>
        <Button
          type="button"
          size="sm"
          variant="ghost"
          disabled={c.busy}
          onClick={() => c.setEditing(false)}
        >
          Cancel
        </Button>
      </div>
    </div>
  ) : (
    <div
      dir="auto"
      data-revealing={isRevealing}
      aria-busy={c.status === 'streaming' || isRevealing}
      className="min-w-0 whitespace-pre-wrap break-words text-sm leading-relaxed"
    >
      {typeof c.content === 'string' ? text : c.content}
      {(c.status === 'streaming' || isRevealing) && (
        <span
          aria-hidden
          className="ms-1 inline-block h-4 w-1 animate-pulse rounded bg-primary align-middle"
        />
      )}
    </div>
  )
}
export function ChatMessageActions() {
  const c = useMessage(),
    [copied, setCopied] = React.useState(false),
    branch = c.branches?.findIndex((item) => item.id === c.branchId) ?? -1
  return (
    <footer className="mt-3 flex flex-wrap items-center gap-1">
      {c.text && (
        <Button
          type="button"
          variant="ghost"
          size="icon-xs"
          aria-label="Copy message"
          disabled={c.busy}
          onClick={() =>
            void c.run(async () => {
              if (c.onCopy) await c.onCopy(c.text)
              else {
                if (!navigator.clipboard) throw new Error('Clipboard is unavailable.')
                await navigator.clipboard.writeText(c.text)
              }
              setCopied(true)
            })
          }
        >
          {copied ? <Check /> : <Copy />}
        </Button>
      )}
      {c.onEdit && (
        <Button
          type="button"
          variant="ghost"
          size="icon-xs"
          aria-label="Edit message"
          disabled={c.busy || c.status === 'streaming'}
          onClick={() => c.setEditing(true)}
        >
          <Pencil />
        </Button>
      )}
      {c.onRetry && (
        <Button
          type="button"
          variant="ghost"
          size="icon-xs"
          aria-label="Regenerate message"
          disabled={c.busy || c.status === 'streaming'}
          onClick={() => void c.run((signal) => c.onRetry!({ signal }))}
        >
          <RotateCcw />
        </Button>
      )}
      {c.onRatingChange &&
        (['up', 'down'] as const).map((v) => (
          <Button
            key={v}
            type="button"
            variant="ghost"
            size="icon-xs"
            aria-label={v === 'up' ? 'Helpful response' : 'Unhelpful response'}
            aria-pressed={c.rating === v}
            onClick={() => c.onRatingChange?.(c.rating === v ? null : v)}
            className={cn(c.rating === v && 'bg-accent text-primary')}
          >
            {v === 'up' ? <ThumbsUp /> : <ThumbsDown />}
          </Button>
        ))}
      {c.branches && c.branches.length > 1 && (
        <div className="ms-auto flex items-center gap-1">
          <Button
            type="button"
            variant="ghost"
            size="icon-xs"
            aria-label="Previous response branch"
            disabled={!c.onBranchChange || branch <= 0}
            onClick={() => c.onBranchChange?.(c.branches![branch - 1].id)}
          >
            <ChevronLeft className="rtl:rotate-180" />
          </Button>
          <span dir="ltr" className="text-[10px] tabular-nums" aria-live="polite">
            {branch < 0 ? '—' : branch + 1} / {c.branches.length}
          </span>
          <Button
            type="button"
            variant="ghost"
            size="icon-xs"
            aria-label="Next response branch"
            disabled={!c.onBranchChange || branch < 0 || branch >= c.branches.length - 1}
            onClick={() => c.onBranchChange?.(c.branches![branch + 1].id)}
          >
            <ChevronRight className="rtl:rotate-180" />
          </Button>
        </div>
      )}
      {c.metadata && (
        <div className="w-full pt-1 text-[10px] text-muted-foreground">{c.metadata}</div>
      )}
    </footer>
  )
}

import * as React from 'react'
import { cn } from '@/lib/utils'

function Textarea({ className, ...props }: React.ComponentProps<'textarea'>) {
  return (
    <textarea
      data-slot="textarea"
      className={cn(
        'flex field-sizing-content min-h-16 w-full rounded-md border border-input bg-transparent px-3 py-2 text-base shadow-xs transition-[color,box-shadow] outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 md:text-sm dark:bg-input/30 dark:aria-invalid:ring-destructive/40',
        className,
      )}
      {...props}
    />
  )
